def finding(id,module,title,claim,sids,recommendation,validation,limits,locations,evidence='Gepinde broninspectie + primaire documentatie; voorstel voor integratievalidatie'):
    assert id not in {f['id'] for f in findings},id
    findings.append(dict(id=id,module=module,title=title,claim=claim,priority='P1',evidence_status=evidence,source_ids=sids,recommendation=recommendation,validation=validation,limits=limits,code_locations=locations,status='proposal'))
finding('UI-024','07','Behoud expliciete coördinaten- en rotatiecontracten','De PDF-app heeft gescheiden pagina-/weergaveruimten en zoomafhankelijke snapafstand; 25 bestaande pure rotatietests slagen.',['R30','R31','R32','R33','A56','A57'],'Maak eenheid/oorsprong/asrichting expliciet en behoud bestaande domeinlogica bij rendererharmonisatie.',['Rotatie, CropBox-offset, userUnit, DPR en zoom in echte viewer.','Annotatie-/snap-/meetpunt blijft gekoppeld aan hetzelfde domeinpunt.'],'Pure tests bewijzen geen pointer-/browser-/meetintegratie; geen universele PDF-unitondersteuning vastgesteld.',['PDF weergave-rotatie.js','PDF pdf-viewport.js:1459','PDF snap-engine.js:782'],'25 bestaande tests uitgevoerd + gepinde broninspectie')
finding('UI-025','07','Bewaar kalibratiegrondslag los van presentatie','De schaalhelper heeft een expliciet afrondingsbeleid voor de schaalstring; de tool kent een tweepuntsflow per pagina.',['R36','A58','A57'],'Leg bronafstand/eenheid/pagina/revisie en presentatieprecisie apart vast; toon ongekalibreerde status.',['Bekende tweede afstand, verschillende pagina’s en heropenen.','Controleer vervolggebruik van afgeronde schaalstring vóór een foutclaim.'],'Volledige schaalstring-consumenten niet getraceerd; geen foutieve hoeveelheid of meetnauwkeurigheid vastgesteld.',['PDF scale-from-measurement.js:24','PDF scale-measure-tool.js:33'])
finding('UI-026','07','Specificeer navigatieprofielen en onderbreken','Apparaatmogelijkheden en gebruikersgewoonten verschillen; aanwezige gebaarfuncties bewijzen nog geen gemounte mobiele route.',['R30','R37','A59','A61','A53'],'Definieer opdrachten met zichtbare mapping, tijdelijke pan/orbit en herstel/cancel per meerstapstaak.',['Muis/trackpad/pen/touch dezelfde taak.','Pointercancel, toolwissel en tweevingeronderbreking op echte apparaten.'],'Geen universele beste mapping en geen volledige mobiele integratie onderzocht.',['PDF touch-gestures.js','PDF main.js','PDF pdf-viewport.js:1544'])
finding('UI-027','07','Maak viewpointcontext expliciet','De werkelijke BIM-engine en capture-request zijn omvangrijker dan het illustratieve native wireframe; screenshot en camera bewaren niet iedere mogelijke BCF-context.',['R34','R35','R38','A60'],'Definieer per workflow model/revisie, objecten, zichtbaarheid, clipping en camera; bewijs rendergereedheid.',['Viewpoint na verborgen selectie en herimport.','Controleer camera-uitkomst voor gebruiker en inhoud van export.'],'Geen volledige BCF-conformanceaudit; screenshotfunctie hoeft geen BCF-export te zijn.',['validator_native.rs:178','Validator captureViewpoint.ts:22','Validator ViewerEngine.ts:1041'])
finding('UI-028','08','Toets touch als afzonderlijk bedieningsprofiel','Webminimum, platformrichtlijn en fysieke duimstudie gebruiken verschillende criteria en eenheden; compact desktopcomfort bewijst geen tabletcomfort.',['A49','A50','A54','A55'],'Vergelijk ruim touchprofiel met bestaand desktopprofiel; toets hitbox, onderlinge ruimte en foute activatie.',['Doelapparaat met vinger/pen en waar relevant handschoenen.','Hybride wissel naar toetsenbord zonder onverwachte layoutsprong.'],'Geen apparaatproef; 0.4-maatvoering is niet gewijzigd. Studiepopulatie is klein en specifiek.',['design/ontwerp-0.4/04-componenten.md'])
finding('UI-029','08','Bied dragvrije en onderbreekbare pointerroutes','Een toetsenbordalternatief alleen dekt web-Dragging Movements niet; pointerverlies en meerstapstools vragen hun eigen contract.',['A51','A52','A53','R30','R37'],'Bied taakpassende tap-/numerieke alternatieven en zichtbare commit/cancel zonder hoverafhankelijkheid.',['Verplaatsen/ordenen zonder drag met één pointer.','Verloren capture en palm-/vingercontact tijdens penactie.'],'Geen palm rejection, native toegankelijkheid of iedere CAD-uitzondering bewezen.',['PDF pdf-viewport.js:1594','PDF touch-gestures.js'])
finding('UI-030','08','Bewijs offline beschikbaarheid na koude herstart','De BIM-validator cachet modelbytes lokaal maar initieert externe worker-/WASM-routes. Dat bewijst nog geen offline start.',['R35','R39','A63','A64','A66'],'Definieer taakgebonden offlinepakket met code/dependencies/data en toon gecontroleerde beschikbaarheid.',['Online voorbereiden, app sluiten, netwerk uit, herstart en kerntaak uitvoeren.','Onderbroken voorbereiding, opslagdruk en latere syncconflicten.'],'Geen vliegtuigmodus-/coldstarttest; warme browsercache kan verschil maken. Geen bestaande offlinebelofte geschonden verklaard.',['Validator ViewerEngine.ts:21','Validator ViewerEngine.ts:231','Validator ViewerEngine.ts:254','Validator modelCache.ts:29'])
finding('UI-031','08','Koppel lokale bytes aan project- en revisie-identiteit','De cache-API en gelezen actieve routes gebruiken fileName als sleutel; foldermethoden zijn afhankelijk van beperkte browsercapabilities.',['R39','R40','A63','A65','A62','A67'],'Scheid menselijke bestandsnaam van stabiele identiteit; maak opslag-/platformmogelijkheden en fouten zichtbaar.',['Twee gebouw.ifc-bestanden met verschillende inhoud, projecten wisselen en herstart.','Doelplatform zonder showDirectoryPicker; bewaren, heropenen en cacheverwijdering.'],'Geen cachebotsing of gebrek aan alle appfallbacks in runtime aangetoond; overige deduplicatieroutes niet volledig onderzocht.',['Validator modelCache.ts:29','Validator AppShell.tsx:193','Validator CenterPanel.tsx:502','Validator LocalProjectStorage.ts:150'])

